// Syncs public photos from Unsplash into src/content/photos/unsplash.yaml.
//
//   npm run photos:unsplash
//
// Commit the generated file. Builds read it and need no key. As Unsplash requires,
// images stay hotlinked to its CDN, and the page credits the photographer and Unsplash.

import { writeFile } from "node:fs/promises";
import { stringify } from "yaml";

const USERNAME = "michaelxi";
const PER_PAGE = 30; // The API maximum.
const SIZES = { thumb: 800, full: 2000 };
const API = process.env.UNSPLASH_API_URL ?? "https://api.unsplash.com";
const OUTPUT = "src/content/photos/unsplash.yaml";

type UnsplashPhoto = {
  id: string;
  created_at: string;
  width: number;
  height: number;
  description: string | null;
  alt_description: string | null;
  urls: { raw: string };
  links: { html: string };
  user: { name: string; links: { html: string } };
};

function fail(message: string): never {
  console.error(`Error: ${message}`);
  process.exit(1);
}

const key = process.env.UNSPLASH_ACCESS_KEY;
const app = process.env.UNSPLASH_APP_NAME;
if (!key || !app) fail("Set UNSPLASH_ACCESS_KEY and UNSPLASH_APP_NAME in .env. See README.md.");

const referral = (url: string) => {
  const link = new URL(url);
  link.searchParams.set("utm_source", app);
  link.searchParams.set("utm_medium", "referral");
  return link.href;
};

// Adding parameters to the raw URL keeps its ixid, which Unsplash requires.
const sized = (raw: string, width: number) => {
  const url = new URL(raw);
  url.searchParams.set("w", String(width));
  url.searchParams.set("fit", "max");
  url.searchParams.set("q", "80");
  url.searchParams.set("auto", "format");
  return url.href;
};

async function fetchPage(page: number) {
  const url = `${API}/users/${USERNAME}/photos?per_page=${PER_PAGE}&order_by=latest&page=${page}`;
  const res = await fetch(url, { headers: { Authorization: `Client-ID ${key}`, "Accept-Version": "v1" } });
  if (res.status === 401) fail("Unsplash rejected the access key.");
  if (res.status === 403) fail("Unsplash refused the request. The hourly rate limit may be used up, so try again later.");
  if (!res.ok) fail(`Unsplash returned HTTP ${res.status}.`);
  return {
    photos: (await res.json()) as UnsplashPhoto[],
    total: Number(res.headers.get("x-total")),
  };
}

const all: UnsplashPhoto[] = [];
let total = 0;
for (let page = 1; ; page++) {
  const result = await fetchPage(page);
  total = result.total;
  all.push(...result.photos);
  if (result.photos.length === 0 || all.length >= total) break;
}

// Stops a bad response from replacing a good album with a partial one.
if (all.length === 0) fail(`Unsplash returned no photos for ${USERNAME}. Nothing was changed.`);
if (all.length !== total) fail(`Expected ${total} photos but received ${all.length}. Nothing was changed.`);

const photographer = all[0].user;
const album = {
  title: "Latest photos",
  date: all[0].created_at.slice(0, 7),
  credit: {
    name: photographer.name,
    profile: referral(photographer.links.html),
    unsplash: referral("https://unsplash.com/"),
  },
  photos: all.map((photo) => ({
    id: photo.id,
    alt: photo.alt_description ?? photo.description ?? "",
    thumb: sized(photo.urls.raw, SIZES.thumb),
    full: sized(photo.urls.raw, SIZES.full),
    width: photo.width,
    height: photo.height,
    link: referral(photo.links.html),
  })),
};

await writeFile(OUTPUT, `# Generated by npm run photos:unsplash. Edits here are overwritten.\n${stringify(album, { lineWidth: 0 })}`);
console.log(`Wrote ${OUTPUT} with ${all.length} photos.`);
const missingAlt = album.photos.filter((photo) => !photo.alt).length;
if (missingAlt > 0) console.log(`${missingAlt} photos have no alt text. Add descriptions on Unsplash, then sync again.`);
